import{_ as t,o as a,c as n,ah as r}from"./chunks/framework.D4KxWb5R.js";const h=JSON.parse('{"title":"Offices and departments","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/administration/referentials.md","filePath":"src/en/guide/administration/referentials.md"}'),s={name:"en/guide/administration/referentials.md"};function i(o,e,c,d,f,l){return a(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="offices-and-departments" tabindex="-1">Offices and departments <a class="header-anchor" href="#offices-and-departments" aria-label="Permalink to &quot;Offices and departments&quot;">​</a></h1><p>The organization&#39;s referentials are for the CEO only. They are not deleted. Zones belong to the <a href="./registry.html#zones">registry</a> and teams have <a href="./teams.html">their own page</a>.</p><h2 id="offices" tabindex="-1">Offices <a class="header-anchor" href="#offices" aria-label="Permalink to &quot;Offices&quot;">​</a></h2><p><strong>Administration → Offices</strong> lists M&#39;City&#39;s physical locations.</p><ol><li><strong>New office</strong>.</li><li>Enter the name and choose the <strong>zone</strong> it is in.</li><li><strong>Create office</strong>.</li></ol><p>Offices are used in the scope of Support L1 and L2 accounts, and as a target for communications. Targeting a zone also reaches the accounts with an office in that zone.</p><h2 id="departments" tabindex="-1">Departments <a class="header-anchor" href="#departments" aria-label="Permalink to &quot;Departments&quot;">​</a></h2><p><strong>Administration → Departments</strong> lists M&#39;City&#39;s units, with the number of accounts attached.</p><ol><li><strong>New department</strong>.</li><li>Enter the name.</li><li><strong>Create department</strong>.</li></ol><p>An account is attached to a department from its account page; a team can be too. Departments are used as a target for communications.</p>',10)])])}const p=t(s,[["render",i]]);export{h as __pageData,p as default};
